1	/* Inference for Llama-2 Transformer model in pure C */
2	
3	#include <stdio.h>
4	#include <stdlib.h>
5	#include <ctype.h>
6	#include <time.h>
7	#include <math.h>
8	#include <string.h>
9	#include <fcntl.h>
10	#if defined _WIN32
11	    #include "win.h"
12	#else
13	    #include <unistd.h>
14	    #include <sys/mman.h>
15	#endif
16	// ----------------------------------------------------------------------------
17	// Transformer model
18	
19	typedef struct {
20	    int dim; // transformer dimension
21	    int hidden_dim; // for ffn layers
22	    int n_layers; // number of layers
23	    int n_heads; // number of query heads
24	    int n_kv_heads; // number of key/value heads (can be < query heads because of multiquery)
25	    int vocab_size; // vocabulary size, usually 256 (byte-level)
26	    int seq_len; // max sequence length
27	} Config;
28	
29	typedef struct {
30	    // token embedding table
31	    float* token_embedding_table;    // (vocab_size, dim)
32	    // weights for rmsnorms
33	    float* rms_att_weight; // (layer, dim) rmsnorm weights
34	    float* rms_ffn_weight; // (layer, dim)
35	    // weights for matmuls. note dim == n_heads * head_size
36	    float* wq; // (layer, dim, n_heads * head_size)
37	    float* wk; // (layer, dim, n_kv_heads * head_size)
38	    float* wv; // (layer, dim, n_kv_heads * head_size)
39	    float* wo; // (layer, n_heads * head_size, dim)
40	    // weights for ffn
41	    float* w1; // (layer, hidden_dim, dim)
42	    float* w2; // (layer, dim, hidden_dim)
43	    float* w3; // (layer, hidden_dim, dim)
44	    // final rmsnorm
45	    float* rms_final_weight; // (dim,)
46	    // (optional) classifier weights for the logits, on the last layer
47	    float* wcls;
48	} TransformerWeights;
49	
50	typedef struct {
51	    // current wave of activations
52	    float *x; // activation at current time stamp (dim,)
53	    float *xb; // same, but inside a residual branch (dim,)
54	    float *xb2; // an additional buffer just for convenience (dim,)
55	    float *hb; // buffer for hidden dimension in the ffn (hidden_dim,)
56	    float *hb2; // buffer for hidden dimension in the ffn (hidden_dim,)
57	    float *q; // query (dim,)
58	    float *k; // key (dim,)
59	    float *v; // value (dim,)
60	    float *att; // buffer for scores/attention values (n_heads, seq_len)
61	    float *logits; // output logits
62	    // kv cache
63	    float* key_cache;   // (layer, seq_len, dim)
64	    float* value_cache; // (layer, seq_len, dim)
65	} RunState;
66	
67	typedef struct {
68	    Config config; // the hyperparameters of the architecture (the blueprint)
69	    TransformerWeights weights; // the weights of the model
70	    RunState state; // buffers for the "wave" of activations in the forward pass
71	    // some more state needed to properly clean up the memory mapping (sigh)
72	    int fd; // file descriptor for memory mapping
73	    float* data; // memory mapped data pointer
74	    ssize_t file_size; // size of the checkpoint file in bytes
75	} Transformer;
76	
77	void malloc_run_state(RunState* s, Config* p) {
78	    // we calloc instead of malloc to keep valgrind happy
79	    int kv_dim = (p->dim * p->n_kv_heads) / p->n_heads;
80	    s->x = calloc(p->dim, sizeof(float));
81	    s->xb = calloc(p->dim, sizeof(float));
82	    s->xb2 = calloc(p->dim, sizeof(float));
83	    s->hb = calloc(p->hidden_dim, sizeof(float));
84	    s->hb2 = calloc(p->hidden_dim, sizeof(float));
85	    s->q = calloc(p->dim, sizeof(float));
86	    s->key_cache = calloc(p->n_layers * p->seq_len * kv_dim, sizeof(float));
87	    s->value_cache = calloc(p->n_layers * p->seq_len * kv_dim, sizeof(float));
88	    s->att = calloc(p->n_heads * p->seq_len, sizeof(float));
89	    s->logits = calloc(p->vocab_size, sizeof(float));
90	    // ensure all mallocs went fine
91	    if (!s->x || !s->xb || !s->xb2 || !s->hb || !s->hb2 || !s->q
92	     || !s->key_cache || !s->value_cache || !s->att || !s->logits) {
93	        fprintf(stderr, "malloc failed!\n");
94	        exit(EXIT_FAILURE);
95	    }
96	}
97	
98	void free_run_state(RunState* s) {
99	    free(s->x);
100	    free(s->xb);
101	    free(s->xb2);
102	    free(s->hb);
103	    free(s->hb2);
104	    free(s->q);
105	    free(s->att);
106	    free(s->logits);
107	    free(s->key_cache);
108	    free(s->value_cache);
109	}
110	
111	void memory_map_weights(TransformerWeights *w, Config* p, float* ptr, int shared_weights) {
112	    int head_size = p->dim / p->n_heads;
113	    // make sure the multiplications below are done in 64bit to fit the parameter counts of 13B+ models
114	    unsigned long long n_layers = p->n_layers;
115	    w->token_embedding_table = ptr;
116	    ptr += p->vocab_size * p->dim;
117	    w->rms_att_weight = ptr;
118	    ptr += n_layers * p->dim;
119	    w->wq = ptr;
120	    ptr += n_layers * p->dim * (p->n_heads * head_size);
121	    w->wk = ptr;
122	    ptr += n_layers * p->dim * (p->n_kv_heads * head_size);
123	    w->wv = ptr;
124	    ptr += n_layers * p->dim * (p->n_kv_heads * head_size);
125	    w->wo = ptr;
126	    ptr += n_layers * (p->n_heads * head_size) * p->dim;
127	    w->rms_ffn_weight = ptr;
128	    ptr += n_layers * p->dim;
129	    w->w1 = ptr;
130	    ptr += n_layers * p->dim * p->hidden_dim;
131	    w->w2 = ptr;
132	    ptr += n_layers * p->hidden_dim * p->dim;
133	    w->w3 = ptr;
134	    ptr += n_layers * p->dim * p->hidden_dim;
135	    w->rms_final_weight = ptr;
136	    ptr += p->dim;
137	    ptr += p->seq_len * head_size / 2; // skip what used to be freq_cis_real (for RoPE)
138	    ptr += p->seq_len * head_size / 2; // skip what used to be freq_cis_imag (for RoPE)
139	    w->wcls = shared_weights ? w->token_embedding_table : ptr;
140	}
141	
142	void read_checkpoint(char* checkpoint, Config* config, TransformerWeights* weights,
143	                     int* fd, float** data, ssize_t* file_size) {
144	    FILE *file = fopen(checkpoint, "rb");
145	    if (!file) { fprintf(stderr, "Couldn't open file %s\n", checkpoint); exit(EXIT_FAILURE); }
146	    // read in the config header
147	    if (fread(config, sizeof(Config), 1, file) != 1) { exit(EXIT_FAILURE); }
148	    // negative vocab size is hacky way of signaling unshared weights. bit yikes.
149	    int shared_weights = config->vocab_size > 0 ? 1 : 0;
150	    config->vocab_size = abs(config->vocab_size);
151	    // figure out the file size
152	    fseek(file, 0, SEEK_END); // move file pointer to end of file
153	    *file_size = ftell(file); // get the file size, in bytes
154	    fclose(file);
155	    // memory map the Transformer weights into the data pointer
156	    *fd = open(checkpoint, O_RDONLY); // open in read only mode
157	    if (*fd == -1) { fprintf(stderr, "open failed!\n"); exit(EXIT_FAILURE); }
158	    *data = mmap(NULL, *file_size, PROT_READ, MAP_PRIVATE, *fd, 0);
159	    if (*data == MAP_FAILED) { fprintf(stderr, "mmap failed!\n"); exit(EXIT_FAILURE); }
160	    float* weights_ptr = *data + sizeof(Config)/sizeof(float);
161	    memory_map_weights(weights, config, weights_ptr, shared_weights);
162	}
163	
164	void build_transformer(Transformer *t, char* checkpoint_path) {
165	    // read in the Config and the Weights from the checkpoint
166	    read_checkpoint(checkpoint_path, &t->config, &t->weights, &t->fd, &t->data, &t->file_size);
167	    // allocate the RunState buffers
168	    malloc_run_state(&t->state, &t->config);
169	}
170	
171	void free_transformer(Transformer* t) {
172	    // close the memory mapping
173	    if (t->data != MAP_FAILED) { munmap(t->data, t->file_size); }
174	    if (t->fd != -1) { close(t->fd); }
175	    // free the RunState buffers
176	    free_run_state(&t->state);
177	}
178	
179	// ----------------------------------------------------------------------------
180	// neural net blocks; the dynamics of the Transformer
181	
182	void rmsnorm(float* o, float* x, float* weight, int size) {
183	    // calculate sum of squares
184	    float ss = 0.0f;
185	    for (int j = 0; j < size; j++) {
186	        ss += x[j] * x[j];
187	    }
188	    ss /= size;
189	    ss += 1e-5f;
190	    ss = 1.0f / sqrtf(ss);
191	    // normalize and scale
192	    for (int j = 0; j < size; j++) {
193	        o[j] = weight[j] * (ss * x[j]);
194	    }
195	}
196	
197	void softmax(float* x, int size) {
198	    // find max value (for numerical stability)
199	    float max_val = x[0];
200	    for (int i = 1; i < size; i++) {
201	        if (x[i] > max_val) {
202	            max_val = x[i];
203	        }
204	    }
205	    // exp and sum
206	    float sum = 0.0f;
207	    for (int i = 0; i < size; i++) {
208	        x[i] = expf(x[i] - max_val);
209	        sum += x[i];
210	    }
211	    // normalize
212	    for (int i = 0; i < size; i++) {
213	        x[i] /= sum;
214	    }
215	}
216	
217	void matmul(float* xout, float* x, float* w, int n, int d) {
218	    // W (d,n) @ x (n,) -> xout (d,)
219	    // by far the most amount of time is spent inside this little function
220	    int i;
221	    #pragma omp parallel for private(i)
222	    for (i = 0; i < d; i++) {
223	        float val = 0.0f;
224	        for (int j = 0; j < n; j++) {
225	            val += w[i * n + j] * x[j];
226	        }
227	        xout[i] = val;
228	    }
229	}
230	
231	float* forward(Transformer* transformer, int token, int pos) {
232	
233	    // a few convenience variables
234	    Config* p = &transformer->config;
235	    TransformerWeights* w = &transformer->weights;
236	    RunState* s = &transformer->state;
237	    float *x = s->x;
238	    int dim = p->dim;
239	    int kv_dim = (p->dim * p->n_kv_heads) / p->n_heads;
240	    int kv_mul = p->n_heads / p->n_kv_heads; // integer multiplier of the kv sharing in multiquery
241	    int hidden_dim =  p->hidden_dim;
242	    int head_size = dim / p->n_heads;
243	
244	    // copy the token embedding into x
245	    float* content_row = w->token_embedding_table + token * dim;
246	    memcpy(x, content_row, dim*sizeof(*x));
247	
248	    // forward all the layers
249	    for(unsigned long long l = 0; l < p->n_layers; l++) {
250	
251	        // attention rmsnorm
252	        rmsnorm(s->xb, x, w->rms_att_weight + l*dim, dim);
253	
254	        // key and value point to the kv cache
255	        int loff = l * p->seq_len * kv_dim; // kv cache layer offset for convenience
256	        s->k = s->key_cache + loff + pos * kv_dim;
257	        s->v = s->value_cache + loff + pos * kv_dim;
258	
259	        // qkv matmuls for this position
260	        matmul(s->q, s->xb, w->wq + l*dim*dim, dim, dim);
261	        matmul(s->k, s->xb, w->wk + l*dim*kv_dim, dim, kv_dim);
262	        matmul(s->v, s->xb, w->wv + l*dim*kv_dim, dim, kv_dim);
263	
264	        // RoPE relative positional encoding: complex-valued rotate q and k in each head
265	        for (int i = 0; i < dim; i+=2) {
266	            int head_dim = i % head_size;
267	            float freq = 1.0f / powf(10000.0f, head_dim / (float)head_size);
268	            float val = pos * freq;
269	            float fcr = cosf(val);
270	            float fci = sinf(val);
271	            int rotn = i < kv_dim ? 2 : 1; // how many vectors? 2 = q & k, 1 = q only
272	            for (int v = 0; v < rotn; v++) {
273	                float* vec = v == 0 ? s->q : s->k; // the vector to rotate (query or key)
274	                float v0 = vec[i];
275	                float v1 = vec[i+1];
276	                vec[i]   = v0 * fcr - v1 * fci;
277	                vec[i+1] = v0 * fci + v1 * fcr;
278	            }
279	        }
280	
281	        // multihead attention. iterate over all heads
282	        int h;
283	        #pragma omp parallel for private(h)
284	        for (h = 0; h < p->n_heads; h++) {
285	            // get the query vector for this head
286	            float* q = s->q + h * head_size;
287	            // attention scores for this head
288	            float* att = s->att + h * p->seq_len;
289	            // iterate over all timesteps, including the current one
290	            for (int t = 0; t <= pos; t++) {
291	                // get the key vector for this head and at this timestep
292	                float* k = s->key_cache + loff + t * kv_dim + (h / kv_mul) * head_size;
293	                // calculate the attention score as the dot product of q and k
294	                float score = 0.0f;
295	                for (int i = 0; i < head_size; i++) {
296	                    score += q[i] * k[i];
297	                }
298	                score /= sqrtf(head_size);
299	                // save the score to the attention buffer
300	                att[t] = score;
301	            }
302	
303	            // softmax the scores to get attention weights, from 0..pos inclusively
304	            softmax(att, pos + 1);
305	
306	            // weighted sum of the values, store back into xb
307	            float* xb = s->xb + h * head_size;
308	            memset(xb, 0, head_size * sizeof(float));
309	            for (int t = 0; t <= pos; t++) {
310	                // get the value vector for this head and at this timestep
311	                float* v = s->value_cache + loff + t * kv_dim + (h / kv_mul) * head_size;
312	                // get the attention weight for this timestep
313	                float a = att[t];
314	                // accumulate the weighted value into xb
315	                for (int i = 0; i < head_size; i++) {
316	                    xb[i] += a * v[i];
317	                }
318	            }
319	        }
320	
321	        // final matmul to get the output of the attention
322	        matmul(s->xb2, s->xb, w->wo + l*dim*dim, dim, dim);
323	
324	        // residual connection back into x
325	        for (int i = 0; i < dim; i++) {
326	            x[i] += s->xb2[i];
327	        }
328	
329	        // ffn rmsnorm
330	        rmsnorm(s->xb, x, w->rms_ffn_weight + l*dim, dim);
331	
332	        // Now for FFN in PyTorch we have: self.w2(F.silu(self.w1(x)) * self.w3(x))
333	        // first calculate self.w1(x) and self.w3(x)
334	        matmul(s->hb, s->xb, w->w1 + l*dim*hidden_dim, dim, hidden_dim);
335	        matmul(s->hb2, s->xb, w->w3 + l*dim*hidden_dim, dim, hidden_dim);
336	
337	        // SwiGLU non-linearity
338	        for (int i = 0; i < hidden_dim; i++) {
339	            float val = s->hb[i];
340	            // silu(x)=x*σ(x), where σ(x) is the logistic sigmoid
341	            val *= (1.0f / (1.0f + expf(-val)));
342	            // elementwise multiply with w3(x)
343	            val *= s->hb2[i];
344	            s->hb[i] = val;
345	        }
346	
347	        // final matmul to get the output of the ffn
348	        matmul(s->xb, s->hb, w->w2 + l*dim*hidden_dim, hidden_dim, dim);
349	
350	        // residual connection
351	        for (int i = 0; i < dim; i++) {
352	            x[i] += s->xb[i];
353	        }
354	    }
355	
356	    // final rmsnorm
357	    rmsnorm(x, x, w->rms_final_weight, dim);
358	
359	    // classifier into logits
360	    matmul(s->logits, x, w->wcls, p->dim, p->vocab_size);
361	    return s->logits;
362	}
363	
364	// ----------------------------------------------------------------------------
365	// The Byte Pair Encoding (BPE) Tokenizer that translates strings <-> tokens
366	
367	typedef struct {
368	    char *str;
369	    int id;
370	} TokenIndex;
371	
372	typedef struct {
373	    char** vocab;
374	    float* vocab_scores;
375	    TokenIndex *sorted_vocab;
376	    int vocab_size;
377	    unsigned int max_token_length;
378	    unsigned char byte_pieces[512]; // stores all single-byte strings
379	} Tokenizer;
380	
381	int compare_tokens(const void *a, const void *b) {
382	    return strcmp(((TokenIndex*)a)->str, ((TokenIndex*)b)->str);
383	}
384	
385	void build_tokenizer(Tokenizer* t, char* tokenizer_path, int vocab_size) {
386	    // i should have written the vocab_size into the tokenizer file... sigh
387	    t->vocab_size = vocab_size;
388	    // malloc space to hold the scores and the strings
389	    t->vocab = (char**)malloc(vocab_size * sizeof(char*));
390	    t->vocab_scores = (float*)malloc(vocab_size * sizeof(float));
391	    t->sorted_vocab = NULL; // initialized lazily
392	    for (int i = 0; i < 256; i++) {
393	        t->byte_pieces[i * 2] = (unsigned char)i;
394	        t->byte_pieces[i * 2 + 1] = '\0';
395	    }
396	    // read in the file
397	    FILE *file = fopen(tokenizer_path, "rb");
398	    if (!file) { fprintf(stderr, "couldn't load %s\n", tokenizer_path); exit(EXIT_FAILURE); }
399	    if (fread(&t->max_token_length, sizeof(int), 1, file) != 1) { fprintf(stderr, "failed read\n"); exit(EXIT_FAILURE); }
400	    int len;
401	    for (int i = 0; i < vocab_size; i++) {
402	        if (fread(t->vocab_scores + i, sizeof(float), 1, file) != 1) { fprintf(stderr, "failed read\n"); exit(EXIT_FAILURE);}
403	        if (fread(&len, sizeof(int), 1, file) != 1) { fprintf(stderr, "failed read\n"); exit(EXIT_FAILURE); }
404	        t->vocab[i] = (char *)malloc(len + 1);
405	        if (fread(t->vocab[i], len, 1, file) != 1) { fprintf(stderr, "failed read\n"); exit(EXIT_FAILURE); }
406	        t->vocab[i][len] = '\0'; // add the string terminating token
407	    }
408	    fclose(file);
409	}
410	
411	void free_tokenizer(Tokenizer* t) {
412	    for (int i = 0; i < t->vocab_size; i++) { free(t->vocab[i]); }
413	    free(t->vocab);
414	    free(t->vocab_scores);
415	    free(t->sorted_vocab);
416	}
417	
418	char* decode(Tokenizer* t, int prev_token, int token) {
419	    char *piece = t->vocab[token];
420	    // following BOS (1) token, sentencepiece decoder strips any leading whitespace (see PR #89)
421	    if (prev_token == 1 && piece[0] == ' ') { piece++; }
422	    // careful, some tokens designate raw bytes, and look like e.g. '<0x01>'
423	    // parse this and convert and return the actual byte
424	    unsigned char byte_val;
425	    if (sscanf(piece, "<0x%02hhX>", &byte_val) == 1) {
426	        piece = (char*)t->byte_pieces + byte_val * 2;
427	    }
428	    return piece;
429	}
430	
431	void safe_printf(char *piece) {
432	    // piece might be a raw byte token, and we only want to print printable chars or whitespace
433	    // because some of the other bytes can be various control codes, backspace, etc.
434	    if (piece == NULL) { return; }
435	    if (piece[0] == '\0') { return; }
436	    if (piece[1] == '\0') {
437	        unsigned char byte_val = piece[0];
438	        if (!(isprint(byte_val) || isspace(byte_val))) {
439	            return; // bad byte, don't print it
440	        }
441	    }
442	    printf("%s", piece);
443	}
444	
445	int str_lookup(char *str, TokenIndex *sorted_vocab, int vocab_size) {
446	    // efficiently find the perfect match for str in vocab, return its index or -1 if not found
447	    TokenIndex tok = { .str = str }; // acts as the key to search for
448	    TokenIndex *res = bsearch(&tok, sorted_vocab, vocab_size, sizeof(TokenIndex), compare_tokens);
449	    return res != NULL ? res->id : -1;
450	}
451	
452	void encode(Tokenizer* t, char *text, int8_t bos, int8_t eos, int *tokens, int *n_tokens) {
453	    // encode the string text (input) into an upper-bound preallocated tokens[] array
454	    // bos != 0 means prepend the BOS token (=1), eos != 0 means append the EOS token (=2)
455	    if (text == NULL) { fprintf(stderr, "cannot encode NULL text\n"); exit(EXIT_FAILURE); }
456	
457	    if (t->sorted_vocab == NULL) {
458	        // lazily malloc and sort the vocabulary
459	        t->sorted_vocab = malloc(t->vocab_size * sizeof(TokenIndex));
460	        for (int i = 0; i < t->vocab_size; i++) {
461	            t->sorted_vocab[i].str = t->vocab[i];
462	            t->sorted_vocab[i].id = i;
463	        }
464	        qsort(t->sorted_vocab, t->vocab_size, sizeof(TokenIndex), compare_tokens);
465	    }
466	
467	    // create a temporary buffer that will store merge candidates of always two consecutive tokens
468	    // *2 for concat, +1 for null terminator +2 for UTF8 (in case max_token_length is 1)
469	    char* str_buffer = malloc((t->max_token_length*2 +1 +2) * sizeof(char));
470	    size_t str_len = 0;
471	
472	    // start at 0 tokens
473	    *n_tokens = 0;
474	
475	    // add optional BOS (=1) token, if desired
476	    if (bos) tokens[(*n_tokens)++] = 1;
477	
478	    // add_dummy_prefix is true by default
479	    // so prepend a dummy prefix token to the input string, but only if text != ""
480	    // TODO: pretty sure this isn't correct in the general case but I don't have the
481	    // energy to read more of the sentencepiece code to figure out what it's doing
482	    if (text[0] != '\0') {
483	        int dummy_prefix = str_lookup(" ", t->sorted_vocab, t->vocab_size);
484	        tokens[(*n_tokens)++] = dummy_prefix;
485	    }
486	
487	    // Okay UTF-8 time. This will get messy. Here is the reference from Wikipedia:
488	    // Code point ↔ UTF-8 conversion
489	    // First code point	Last code point	Byte 1	Byte 2	Byte 3	Byte 4
490	    // U+0000	U+007F	    0xxxxxxx
491	    // U+0080	U+07FF	    110xxxxx	10xxxxxx
492	    // U+0800	U+FFFF	    1110xxxx	10xxxxxx	10xxxxxx
493	    // U+10000	U+10FFFF    11110xxx	10xxxxxx	10xxxxxx	10xxxxxx
494	
495	    // process the raw (UTF-8) byte sequence of the input string
496	    for (char *c = text; *c != '\0'; c++) {
497	
498	        // reset buffer if the current byte is ASCII or a leading byte
499	        // 0xC0 is 11000000, so (*c & 0xC0) keeps the first 2 bits and zeros the rest
500	        // 0x80 is 10000000
501	        // in UTF-8, all continuation bytes start with "10" in first two bits
502	        // so in English this is: "if this byte is not a continuation byte"
503	        if ((*c & 0xC0) != 0x80) {
504	            // this byte must be either a leading byte (11...) or an ASCII char (0x...)
505	            // => reset our location, as we're starting a new UTF-8 codepoint
506	            str_len = 0;
507	        }
508	
509	        // append the current byte to the buffer
510	        str_buffer[str_len++] = *c; // ++ is post-increment, incremented after this line
511	        str_buffer[str_len] = '\0';
512	
513	        // while the next character is a continuation byte, continue appending
514	        // but if there are too many of them, just stop to avoid overruning str_buffer size.
515	        if ((*(c+1) & 0xC0) == 0x80 && str_len < 4) {
516	            continue;
517	        }
518	
519	        // ok c+1 is not a continuation byte, so we've read in a full codepoint
520	        int id = str_lookup(str_buffer, t->sorted_vocab, t->vocab_size);
521	
522	        if (id != -1) {
523	            // we found this codepoint in vocab, add it as a token
524	            tokens[(*n_tokens)++] = id;
525	        } else {
526	            // byte_fallback encoding: just encode each byte as a token
527	            // +3 is here because the first 3 vocab elements are <unk>, <s>, </s>
528	            // so the individual bytes only start at index 3
529	            for (int i=0; i < str_len; i++) {
530	                tokens[(*n_tokens)++] = (unsigned char)str_buffer[i] + 3;
531	            }
532	        }
533	        str_len = 0; // protect against a sequence of stray UTF8 continuation bytes
534	    }
535	
536	    // merge the best consecutive pair each iteration, according the scores in vocab_scores
537	    while (1) {
538	        float best_score = -1e10;
539	        int best_id = -1;
540	        int best_idx = -1;
541	
542	        for (int i=0; i < (*n_tokens-1); i++) {
543	            // check if we can merge the pair (tokens[i], tokens[i+1])
544	            sprintf(str_buffer, "%s%s", t->vocab[tokens[i]], t->vocab[tokens[i+1]]);
545	            int id = str_lookup(str_buffer, t->sorted_vocab, t->vocab_size);
546	            if (id != -1 && t->vocab_scores[id] > best_score) {
547	                // this merge pair exists in vocab! record its score and position
548	                best_score = t->vocab_scores[id];
549	                best_id = id;
550	                best_idx = i;
551	            }
552	        }
553	
554	        if (best_idx == -1) {
555	            break; // we couldn't find any more pairs to merge, so we're done
556	        }
557	
558	        // merge the consecutive pair (best_idx, best_idx+1) into new token best_id
559	        tokens[best_idx] = best_id;
560	        // delete token at position best_idx+1, shift the entire sequence back 1
561	        for (int i = best_idx+1; i < (*n_tokens-1); i++) {
562	            tokens[i] = tokens[i+1];
563	        }
564	        (*n_tokens)--; // token length decreased
565	    }
566	
567	    // add optional EOS (=2) token, if desired
568	    if (eos) tokens[(*n_tokens)++] = 2;
569	
570	    free(str_buffer);
571	}
572	
573	// ----------------------------------------------------------------------------
574	// The Sampler, which takes logits and returns a sampled token
575	// sampling can be done in a few ways: greedy argmax, sampling, top-p sampling
576	
577	typedef struct {
578	    float prob;
579	    int index;
580	} ProbIndex; // struct used when sorting probabilities during top-p sampling
581	
582	typedef struct {
583	    int vocab_size;
584	    ProbIndex* probindex; // buffer used in top-p sampling
585	    float temperature;
586	    float topp;
587	    unsigned long long rng_state;
588	} Sampler;
589	
590	int sample_argmax(float* probabilities, int n) {
591	    // return the index that has the highest probability
592	    int max_i = 0;
593	    float max_p = probabilities[0];
594	    for (int i = 1; i < n; i++) {
595	        if (probabilities[i] > max_p) {
596	            max_i = i;
597	            max_p = probabilities[i];
598	        }
599	    }
600	    return max_i;
601	}
602	
603	int sample_mult(float* probabilities, int n, float coin) {
604	    // sample index from probabilities (they must sum to 1!)
605	    // coin is a random number in [0, 1), usually from random_f32()
606	    float cdf = 0.0f;
607	    for (int i = 0; i < n; i++) {
608	        cdf += probabilities[i];
609	        if (coin < cdf) {
610	            return i;
611	        }
612	    }
613	    return n - 1; // in case of rounding errors
614	}
615	
616	int compare(const void* a, const void* b) {
617	    ProbIndex* a_ = (ProbIndex*) a;
618	    ProbIndex* b_ = (ProbIndex*) b;
619	    if (a_->prob > b_->prob) return -1;
620	    if (a_->prob < b_->prob) return 1;
621	    return 0;
622	}
623	
624	int sample_topp(float* probabilities, int n, float topp, ProbIndex* probindex, float coin) {
625	    // top-p sampling (or "nucleus sampling") samples from the smallest set of
626	    // tokens that exceed probability topp. This way we never sample tokens that
627	    // have very low probabilities and are less likely to go "off the rails".
628	    // coin is a random number in [0, 1), usually from random_f32()
629	
630	    int n0 = 0;
631	    // quicksort indices in descending order of probabilities
632	    // values smaller than (1 - topp) / (n - 1) cannot be part of the result
633	    // so for efficiency we crop these out as candidates before sorting
634	    const float cutoff = (1.0f - topp) / (n - 1);
635	    for (int i = 0; i < n; i++) {
636	        if (probabilities[i] >= cutoff) {
637	            probindex[n0].index = i;
638	            probindex[n0].prob = probabilities[i];
639	            n0++;
640	        }
641	    }
642	    qsort(probindex, n0, sizeof(ProbIndex), compare);
643	
644	    // truncate the list where cumulative probability exceeds topp
645	    float cumulative_prob = 0.0f;
646	    int last_idx = n0 - 1; // in case of rounding errors consider all elements
647	    for (int i = 0; i < n0; i++) {
648	        cumulative_prob += probindex[i].prob;
649	        if (cumulative_prob > topp) {
650	            last_idx = i;
651	            break; // we've exceeded topp by including last_idx
652	        }
653	    }
654	
655	    // sample from the truncated list
656	    float r = coin * cumulative_prob;
657	    float cdf = 0.0f;
658	    for (int i = 0; i <= last_idx; i++) {
659	        cdf += probindex[i].prob;
660	        if (r < cdf) {
661	            return probindex[i].index;
662	        }
663	    }
664	    return probindex[last_idx].index; // in case of rounding errors
665	}
666	
667	void build_sampler(Sampler* sampler, int vocab_size, float temperature, float topp, unsigned long long rng_seed) {
668	    sampler->vocab_size = vocab_size;
669	    sampler->temperature = temperature;
670	    sampler->topp = topp;
671	    sampler->rng_state = rng_seed;
672	    // buffer only used with nucleus sampling; may not need but it's ~small
673	    sampler->probindex = malloc(sampler->vocab_size * sizeof(ProbIndex));
674	}
675	
676	void free_sampler(Sampler* sampler) {
677	    free(sampler->probindex);
678	}
679	
680	unsigned int random_u32(unsigned long long *state) {
681	    // xorshift rng: https://en.wikipedia.org/wiki/Xorshift#xorshift.2A
682	    *state ^= *state >> 12;
683	    *state ^= *state << 25;
684	    *state ^= *state >> 27;
685	    return (*state * 0x2545F4914F6CDD1Dull) >> 32;
686	}
687	float random_f32(unsigned long long *state) { // random float32 in [0,1)
688	    return (random_u32(state) >> 8) / 16777216.0f;
689	}
690	
691	int sample(Sampler* sampler, float* logits) {
692	    // sample the token given the logits and some hyperparameters
693	    int next;
694	    if (sampler->temperature == 0.0f) {
695	        // greedy argmax sampling: take the token with the highest probability
696	        next = sample_argmax(logits, sampler->vocab_size);
697	    } else {
698	        // apply the temperature to the logits
699	        for (int q=0; q<sampler->vocab_size; q++) { logits[q] /= sampler->temperature; }
700	        // apply softmax to the logits to get the probabilities for next token
701	        softmax(logits, sampler->vocab_size);
702	        // flip a (float) coin (this is our source of entropy for sampling)
703	        float coin = random_f32(&sampler->rng_state);
704	        // we sample from this distribution to get the next token
705	        if (sampler->topp <= 0 || sampler->topp >= 1) {
706	            // simply sample from the predicted probability distribution
707	            next = sample_mult(logits, sampler->vocab_size, coin);
708	        } else {
709	            // top-p (nucleus) sampling, clamping the least likely tokens to zero
710	            next = sample_topp(logits, sampler->vocab_size, sampler->topp, sampler->probindex, coin);
711	        }
712	    }
713	    return next;
714	}
715	
716	// ----------------------------------------------------------------------------
717	// utilities: time
718	
719	long time_in_ms() {
720	    // return time in milliseconds, for benchmarking the model speed
721	    struct timespec time;
722	    clock_gettime(CLOCK_REALTIME, &time);
723	    return time.tv_sec * 1000 + time.tv_nsec / 1000000;
724	}
725	
726	// ----------------------------------------------------------------------------
727	// generation loop
728	
729	void generate(Transformer *transformer, Tokenizer *tokenizer, Sampler *sampler, char *prompt, int steps) {
730	    char *empty_prompt = "";
731	    if (prompt == NULL) { prompt = empty_prompt; }
732	
733	    // encode the (string) prompt into tokens sequence
734	    int num_prompt_tokens = 0;
735	    int* prompt_tokens = (int*)malloc((strlen(prompt)+3) * sizeof(int)); // +3 for '\0', ?BOS, ?EOS
736	    encode(tokenizer, prompt, 1, 0, prompt_tokens, &num_prompt_tokens);
737	    if (num_prompt_tokens < 1) {
738	        fprintf(stderr, "something is wrong, expected at least 1 prompt token\n");
739	        exit(EXIT_FAILURE);
740	    }
741	
742	    // start the main loop
743	    long start = 0;  // used to time our code, only initialized after first iteration
744	    int next;        // will store the next token in the sequence
745	    int token = prompt_tokens[0]; // kick off with the first token in the prompt
746	    int pos = 0;     // position in the sequence
747	    while (pos < steps) {
748	
749	        // forward the transformer to get logits for the next token
750	        float* logits = forward(transformer, token, pos);
751	
752	        // advance the state machine
753	        if (pos < num_prompt_tokens - 1) {
754	            // if we are still processing the input prompt, force the next prompt token
755	            next = prompt_tokens[pos + 1];
756	        } else {
757	            // otherwise sample the next token from the logits
758	            next = sample(sampler, logits);
759	        }
760	        pos++;
761	
762	        // data-dependent terminating condition: the BOS (=1) token delimits sequences
763	        if (next == 1) { break; }
764	
765	        // print the token as string, decode it with the Tokenizer object
766	        char* piece = decode(tokenizer, token, next);
767	        safe_printf(piece); // same as printf("%s", piece), but skips "unsafe" bytes
768	        fflush(stdout);
769	        token = next;
770	
771	        // init the timer here because the first iteration can be slower
772	        if (start == 0) { start = time_in_ms(); }
773	    }
774	    printf("\n");
775	
776	    // report achieved tok/s (pos-1 because the timer starts after first iteration)
777	    if (pos > 1) {
778	        long end = time_in_ms();
779	        fprintf(stderr, "achieved tok/s: %f\n", (pos-1) / (double)(end-start)*1000);
780	    }
781	
782	    free(prompt_tokens);
783	}
784	
785	void read_stdin(const char* guide, char* buffer, size_t bufsize) {
786	    // read a line from stdin, up to but not including \n
787	    printf("%s", guide);
788	    if (fgets(buffer, bufsize, stdin) != NULL) {
789	        size_t len = strlen(buffer);
790	        if (len > 0 && buffer[len - 1] == '\n') {
791	            buffer[len - 1] = '\0'; // strip newline
792	        }
793	    }
794	}
795	
796	// ----------------------------------------------------------------------------
797	// chat loop
798	// I manually inspected the tokens for a few chat conversations compared to
799	// python reference and that seemed ok, but this was not thoroughly tested and
800	// is not safely implemented, it's more a proof of concept atm.
801	
802	void chat(Transformer *transformer, Tokenizer *tokenizer, Sampler *sampler,
803	          char *cli_user_prompt, char *cli_system_prompt, int steps) {
804	
805	    // buffers for reading the system prompt and user prompt from stdin
806	    // you'll notice they are soomewhat haphazardly and unsafely set atm
807	    char system_prompt[512];
808	    char user_prompt[512];
809	    char rendered_prompt[1152];
810	    int num_prompt_tokens = 0;
811	    int* prompt_tokens = (int*)malloc(1152 * sizeof(int));
812	    int user_idx;
813	
814	    // start the main loop
815	    int8_t user_turn = 1; // user starts
816	    int next;        // will store the next token in the sequence
817	    int token;       // stores the current token to feed into the transformer
818	    int prev_token;
819	    int pos = 0;     // position in the sequence
820	    while (pos < steps) {
821	
822	        // when it is the user's turn to contribute tokens to the dialog...
823	        if (user_turn) {
824	            // get the (optional) system prompt at position 0
825	            if (pos == 0) {
826	                // at position 0, the user can also contribute a system prompt
827	                if (cli_system_prompt == NULL) {
828	                    // system prompt was not passed in, attempt to get it from stdin
829	                    read_stdin("Enter system prompt (optional): ", system_prompt, sizeof(system_prompt));
830	                } else {
831	                    // system prompt was passed in, use it
832	                    strcpy(system_prompt, cli_system_prompt);
833	                }
834	            }
835	            // get the user prompt
836	            if (pos == 0 && cli_user_prompt != NULL) {
837	                // user prompt for position 0 was passed in, use it
838	                strcpy(user_prompt, cli_user_prompt);
839	            } else {
840	                // otherwise get user prompt from stdin
841	                read_stdin("User: ", user_prompt, sizeof(user_prompt));
842	            }
843	            // render user/system prompts into the Llama 2 Chat schema
844	            if (pos == 0 && system_prompt[0] != '\0') {
845	                char system_template[] = "[INST] <<SYS>>\n%s\n<</SYS>>\n\n%s [/INST]";
846	                sprintf(rendered_prompt, system_template, system_prompt, user_prompt);
847	            } else {
848	                char user_template[] = "[INST] %s [/INST]";
849	                sprintf(rendered_prompt, user_template, user_prompt);
850	            }
851	            // encode the rendered prompt into tokens
852	            encode(tokenizer, rendered_prompt, 1, 0, prompt_tokens, &num_prompt_tokens);
853	            user_idx = 0; // reset the user index
854	            user_turn = 0;
855	            printf("Assistant: ");
856	        }
857	
858	        // determine the token to pass into the transformer next
859	        if (user_idx < num_prompt_tokens) {
860	            // if we are still processing the input prompt, force the next prompt token
861	            token = prompt_tokens[user_idx++];
862	        } else {
863	            // otherwise use the next token sampled from previous turn
864	            token = next;
865	        }
866	        // EOS (=2) token ends the Assistant turn
867	        if (token == 2) { user_turn = 1; }
868	
869	        // forward the transformer to get logits for the next token
870	        float* logits = forward(transformer, token, pos);
871	        next = sample(sampler, logits);
872	        pos++;
873	
874	        if (user_idx >= num_prompt_tokens && next != 2) {
875	            // the Assistant is responding, so print its output
876	            char* piece = decode(tokenizer, token, next);
877	            safe_printf(piece); // same as printf("%s", piece), but skips "unsafe" bytes
878	            fflush(stdout);
879	        }
880	        if (next == 2) { printf("\n"); }
881	    }
882	    printf("\n");
883	    free(prompt_tokens);
884	}
885	
886	
887	// ----------------------------------------------------------------------------
888	// CLI, include only if not testing
889	#ifndef TESTING
890	
891	void error_usage() {
892	    fprintf(stderr, "Usage:   run <checkpoint> [options]\n");
893	    fprintf(stderr, "Example: run model.bin -n 256 -i \"Once upon a time\"\n");
894	    fprintf(stderr, "Options:\n");
895	    fprintf(stderr, "  -t <float>  temperature in [0,inf], default 1.0\n");
896	    fprintf(stderr, "  -p <float>  p value in top-p (nucleus) sampling in [0,1] default 0.9\n");
897	    fprintf(stderr, "  -s <int>    random seed, default time(NULL)\n");
898	    fprintf(stderr, "  -n <int>    number of steps to run for, default 256. 0 = max_seq_len\n");
899	    fprintf(stderr, "  -i <string> input prompt\n");
900	    fprintf(stderr, "  -z <string> optional path to custom tokenizer\n");
901	    fprintf(stderr, "  -m <string> mode: generate|chat, default: generate\n");
902	    fprintf(stderr, "  -y <string> (optional) system prompt in chat mode\n");
903	    exit(EXIT_FAILURE);
904	}
905	
906	int main(int argc, char *argv[]) {
907	
908	    // default parameters
909	    char *checkpoint_path = NULL;  // e.g. out/model.bin
910	    char *tokenizer_path = "tokenizer.bin";
911	    float temperature = 1.0f;   // 0.0 = greedy deterministic. 1.0 = original. don't set higher
912	    float topp = 0.9f;          // top-p in nucleus sampling. 1.0 = off. 0.9 works well, but slower
913	    int steps = 256;            // number of steps to run for
914	    char *prompt = NULL;        // prompt string
915	    unsigned long long rng_seed = 0; // seed rng with time by default
916	    char *mode = "generate";    // generate|chat
917	    char *system_prompt = NULL; // the (optional) system prompt to use in chat mode
918	
919	    // poor man's C argparse so we can override the defaults above from the command line
920	    if (argc >= 2) { checkpoint_path = argv[1]; } else { error_usage(); }
921	    for (int i = 2; i < argc; i+=2) {
922	        // do some basic validation
923	        if (i + 1 >= argc) { error_usage(); } // must have arg after flag
924	        if (argv[i][0] != '-') { error_usage(); } // must start with dash
925	        if (strlen(argv[i]) != 2) { error_usage(); } // must be -x (one dash, one letter)
926	        // read in the args
927	        if (argv[i][1] == 't') { temperature = atof(argv[i + 1]); }
928	        else if (argv[i][1] == 'p') { topp = atof(argv[i + 1]); }
929	        else if (argv[i][1] == 's') { rng_seed = atoi(argv[i + 1]); }
930	        else if (argv[i][1] == 'n') { steps = atoi(argv[i + 1]); }
931	        else if (argv[i][1] == 'i') { prompt = argv[i + 1]; }
932	        else if (argv[i][1] == 'z') { tokenizer_path = argv[i + 1]; }
933	        else if (argv[i][1] == 'm') { mode = argv[i + 1]; }
934	        else if (argv[i][1] == 'y') { system_prompt = argv[i + 1]; }
935	        else { error_usage(); }
936	    }
937	
938	    // parameter validation/overrides
939	    if (rng_seed <= 0) rng_seed = (unsigned int)time(NULL);
940	    if (temperature < 0.0) temperature = 0.0;
941	    if (topp < 0.0 || 1.0 < topp) topp = 0.9;
942	    if (steps < 0) steps = 0;
943	
944	    // build the Transformer via the model .bin file
945	    Transformer transformer;
946	    build_transformer(&transformer, checkpoint_path);
947	    if (steps == 0 || steps > transformer.config.seq_len) steps = transformer.config.seq_len; // override to ~max length
948	
949	    // build the Tokenizer via the tokenizer .bin file
950	    Tokenizer tokenizer;
951	    build_tokenizer(&tokenizer, tokenizer_path, transformer.config.vocab_size);
952	
953	    // build the Sampler
954	    Sampler sampler;
955	    build_sampler(&sampler, transformer.config.vocab_size, temperature, topp, rng_seed);
956	
957	    // run!
958	    if (strcmp(mode, "generate") == 0) {
959	        generate(&transformer, &tokenizer, &sampler, prompt, steps);
960	    } else if (strcmp(mode, "chat") == 0) {
961	        chat(&transformer, &tokenizer, &sampler, prompt, system_prompt, steps);
962	    } else {
963	        fprintf(stderr, "unknown mode: %s\n", mode);
964	        error_usage();
965	    }
966	
967	    // memory and file handles cleanup
968	    free_sampler(&sampler);
969	    free_tokenizer(&tokenizer);
970	    free_transformer(&transformer);
971	    return 0;
972	}
973	#endif
