18	    int dim, hidden_dim, n_layers, n_heads, n_kv_heads, vocab_size, seq_len;
19	} Config;
20	
21	static Config cfg;
22	static int dim, hid, nl, nh, nkv, V, S, hs, kvd, qkvd, kv_mul;
23	static float *emb, *wcls, *rms_att, *rms_ffn, *rms_final;
24	static float **wqkv, **wo, **w13, **w2; /* per-layer pointers into one block */
25	static float *kcache, *vcache;          /* (layer, seq_len, kv_dim) */
26	static float *rope_cos, *rope_sin;      /* (seq_len, head_size/2) */
27	
28	#define CHUNK 512 /* max positions forwarded together */
29	static float *bx, *bxb, *bxb2, *bqkv, *bh13, *bhb, *batt, *blogits;
30	
31	static void *xalloc(size_t n) {
32	    void *p = NULL;
33	    if (n == 0) n = 1;
34	    if (posix_memalign(&p, 16384, n) != 0 || !p) { fprintf(stderr, "alloc failed\n"); exit(1); }
35	    return p;
36	}
37	
38	static void pread_all(int fd, void *dst, size_t n, off_t off) {
39	    char *d = dst;
40	    while (n > 0) {
41	        ssize_t r = pread(fd, d, n > (1u << 30) ? (1u << 30) : n, off);
42	        if (r <= 0) { fprintf(stderr, "read failed\n"); exit(1); }
43	        d += r; n -= (size_t)r; off += r;
44	    }
45	}
46	
47	static void load_model(const char *path) {
48	    int fd = open(path, O_RDONLY);
49	    if (fd < 0) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
50	    pread_all(fd, &cfg, sizeof(Config), 0);
