    size_t L = (size_t)nl, D = dim, H = hid, KV = kvd, VV = V;
    size_t o_emb = 0;
    size_t o_rmsatt = o_emb + VV * D;
    size_t o_wq = o_rmsatt + L * D;
    size_t o_wk = o_wq + L * D * D;
    size_t o_wv = o_wk + L * D * KV;
    size_t o_wo = o_wv + L * D * KV;
